function escapeHtml(value = '') { return String(value).replace(/[&<>"']/g, ch => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#039;' }[ch])); }
function initials(name='') { return name.split(' ').map(x => x[0]).slice(0,2).join('').toUpperCase(); }
function levelFor(score) { return score >= 90 ? 'Приоритетная' : score >= 70 ? 'Готовая' : score >= 40 ? 'Рабочая' : 'Черновик'; }
function levelClass(level) { return ({ 'Приоритетная':'purple', 'Готовая':'green', 'Рабочая':'blue', 'Черновик':'orange' })[level] || 'gray'; }
function rarityFor(score) { return score >= 90 ? ['Легенда','legend'] : score >= 70 ? ['Эпик','epic'] : score >= 40 ? ['Рабочая','common'] : ['Набросок','draft']; }
function rarityBadge(score) { const [label,tier]=rarityFor(score); return `<span class="rarity-badge rarity-${tier}"><i class="rarity-spark" aria-hidden="true"></i>${label}</span>`; }
function workspaceProgressMarkup() {
 const published=state.tasks.filter(t=>t.status==='published'); const ids=new Set(published.map(t=>t.id));
 const offers=state.offers.filter(o=>ids.has(o.taskId));
 const steps=[['Задача опубликована',published.length>0],['Команда выбрана',offers.some(o=>o.status==='accepted')],['Результат подтверждён',offers.some(o=>o.progressConfirmed)]];
 const done=steps.filter(x=>x[1]).length;
 return `<section class="workspace-progress" aria-label="Прогресс проекта"><div class="workspace-progress-head"><strong>Путь проекта</strong><span>${done} из ${steps.length}</span></div><div class="workspace-progress-track" style="--progress:${Math.round(done/steps.length*100)}%"><i></i></div><ul>${steps.map(([label,complete])=>`<li class="${complete?'complete':''}"><span class="progress-check" aria-hidden="true">${complete?'✓':'·'}</span>${label}</li>`).join('')}</ul></section>`;
}
function achievementMarkup(tasks,offers) {
 const items=[
  ['✦','Первый бриф','Опубликована задача',tasks.length>0,'red'],
  ['◈','Готовность 70+','Есть задача, готовая к работе',tasks.some(t=>t.score>=70),'gold'],
  ['↗','Первый отклик','Команда отправила предложение',offers.length>0,'dark'],
  ['✓','Результат проверен','Бизнес отметил выполненный этап',offers.some(o=>o.progressConfirmed),'green'],
 ];
 const unlocked=items.filter(x=>x[3]).length;
 return `<section class="achievement-panel" aria-labelledby="achievement-title"><div class="achievement-heading"><div><h2 id="achievement-title">Знаки прогресса</h2><p>Открываются по событиям в проекте</p></div><span>${unlocked} из ${items.length}</span></div><div class="achievement-grid">${items.map(([glyph,title,detail,earned,color],i)=>`<article class="achievement ${earned?'earned':'locked'}" style="--stagger:${i*65}ms"><span class="achievement-icon icon-${color}" aria-hidden="true">${glyph}</span><span class="achievement-copy"><strong>${title}</strong><small>${detail}</small></span></article>`).join('')}</div></section>`;
}
function toast(message) { const root = document.getElementById('toast-root'); const el = document.createElement('div'); el.className = 'toast'; el.textContent = message; root.appendChild(el); setTimeout(() => el.remove(), 3400); }
function nextActions(item) { return breakdownFor(item).filter(x => x.points < x.weight).sort((a,b) => (b.weight-b.points) - (a.weight-a.points)).slice(0,3); }
function scoreRing(score) { return `<div class="score-ring" style="background:conic-gradient(#63d1d5 0 ${score}%, rgba(255,255,255,.17) ${score}% 100%)"><div class="score-in"><strong>${score}</strong><span>из 100</span></div></div>`; }
function metric(label, value, detail) { return `<div class="card metric"><div class="eyebrow">${label}</div><div class="value">${value}</div><div class="detail">${detail}</div></div>`; }
function icon(name) {
 const shapes={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',create:'<path d="M12 5v14M5 12h14"/>',catalog:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',offers:'<path d="M4 4h16v12H9l-5 4V4Z"/><path d="M8 8h8M8 12h5"/>',analytics:'<path d="M4 4v16h17M9 15v-4M14 15V7M19 15v-6"/>',arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>'};
 return `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[name]||shapes.catalog}</svg>`;
}
function navButton(id, unused, label) { return `<button aria-label="${label}" ${state.view===id?'aria-current="page"':''} class="${state.view === id ? 'active' : ''}" data-view="${id}"><span class="nav-icon">${icon(id)}</span><span>${label}</span>${id==='offers'&&state.offers.some(o=>o.status==='pending')?`<small class="nav-count">${state.offers.filter(o=>o.status==='pending').length}</small>`:''}</button>`; }
function renderShell() {
 document.getElementById('app').innerHTML = `<aside class="sidebar">
 <div class="brand"><div class="brand-mark">${icon('check')}</div><div><strong>taskready<span>.</span></strong><small>От идеи к результату</small></div></div>
 <div class="workspace-label">Рабочее пространство</div>
 <nav class="nav" aria-label="Основная навигация">${navButton('dashboard','','Обзор')}${navButton('catalog','','Задачи')}${navButton('offers','','Отклики')}${navButton('analytics','','Аналитика')}</nav>
 ${state.role==='business'?`<button class="btn sidebar-create" data-view="create">${icon('create')} Создать задачу</button>`:''}
 <div class="sidebar-bottom">${workspaceProgressMarkup()}<div class="sidebar-caption"><span class="status-dot"></span> ${DEMO?'Автономное демо':'Данные на сервере'}</div><p>${DEMO?'Учебные данные · локальный анализ':'Задачи сохраняются в вашем аккаунте.'}</p><div class="profile"><div class="avatar">А</div><div><strong>${escapeHtml(currentIdentity().name)}</strong><small>${DEMO?'Пространство хакатона':'Рабочий аккаунт'}</small></div></div></div>
 </aside><main class="main"><header class="topbar"><div class="breadcrumb">Рабочее пространство <span>/</span> <strong>${state.view==='create'?'Новая задача':titleForView()}</strong></div><div class="top-actions">${DEMO?`<span class="role-label">Демо-роли</span><div class="role-switch"><button class="${state.role==='business'?'active':''}" data-role="business">Бизнес</button><button class="${state.role==='team'?'active':''}" data-role="team">Команда</button></div>`:`<span class="badge green">${state.role==='business'?'Бизнес':'Команда'}</span><button class="btn small" id="logout">Выйти</button>`}</div></header><section class="content">${renderView()}</section><footer class="page-footer"><span>TaskReady · Пространство для совместной работы</span><span>Сначала ясность. Затем действие.</span></footer></main>`;
 bindEvents();
}
function titleForView() { return ({ dashboard:'Обзор', catalog:'Каталог задач', offers:'Отклики', analytics:'Аналитика' })[state.view] || 'Обзор'; }
function renderView() { return ({ dashboard: renderDashboard, create: renderCreate, catalog: renderCatalog, offers: renderOffers, analytics: renderAnalytics })[state.view](); }
function renderDashboard() {
 const tasks=state.tasks.filter(t=>t.status==='published'&&(state.role==='team'||t.owner===currentIdentity().id));
 const avg=tasks.length?Math.round(tasks.reduce((v,t)=>v+t.score,0)/tasks.length):0;
 const pending=state.offers.filter(o=>o.status==='pending');
 const ready=tasks.filter(t=>t.score>=70).length;
 return `<div class="page-heading overview-heading"><div><div class="eyebrow">Обзор пространства</div><h1>Хорошие идеи.<br><em>Понятные задачи.</em></h1><p>Всё, что нужно для следующего шага вашего проекта.</p></div>${state.role==='business'?`<button class="btn primary" data-action="new-task">${icon('create')} Новая задача</button>`:`<button class="btn primary" data-view="catalog">Найти задачу ${icon('arrow')}</button>`}</div>
 <div class="summary-strip"><div><span>Опубликовано задач</span><strong>${String(tasks.length).padStart(2,'0')}</strong><small>В открытом каталоге</small></div><div><span>Готовы к работе</span><strong>${String(ready).padStart(2,'0')}<small> / ${tasks.length}</small></strong><small>Готовность от 70 баллов</small></div><div><span>Средняя готовность</span><strong class="readiness-stat"><span class="readiness-orb" style="--score:${avg}%"><b>${avg}</b></span><small> / 100</small></strong><small>По опубликованным задачам</small></div><div><span>Ожидают решения</span><strong>${String(pending.length).padStart(2,'0')}<i class="metric-dot"></i></strong><button class="text-link" data-view="offers">Посмотреть отклики</button></div></div>
 ${achievementMarkup(tasks,visibleOffers())}
 <div class="overview-layout"><div><section class="task-section"><div class="section-heading"><div><h2>${state.role==='team'?'Задачи для команд':'Ваши задачи'} <span>${tasks.length}</span></h2><p>От первого описания до готового брифа.</p></div><button class="text-link" data-view="catalog">Весь каталог ${icon('arrow')}</button></div><div class="task-controls"><label class="task-search"><svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><input id="overview-search" type="search" placeholder="Найти задачу…" aria-label="Поиск по задачам" /></label><select id="overview-sort" aria-label="Порядок задач"><option value="default">По порядку</option><option value="score">Сначала готовые</option><option value="gaps">Нужны детали</option></select></div><div class="task-filterbar"><div class="task-filters" role="group" aria-label="Фильтр готовности"><button class="active" data-readiness="all" aria-pressed="true">Все <span>${tasks.length}</span></button><button data-readiness="ready" aria-pressed="false">Готовы <span>${ready}</span></button><button data-readiness="draft" aria-pressed="false">Нужны детали <span>${tasks.length-ready}</span></button></div><span id="overview-count" aria-live="polite">${tasks.length} из ${tasks.length}</span></div><div class="task-table"><div class="task-table-head"><span>Задача</span><span>Готовность</span><span></span></div>${tasks.map((t,i)=>`<button class="task-row" data-task="${t.id}" data-score="${t.score}" data-order="${i}" data-search="${escapeHtml(`${t.title} ${t.context} ${t.industry}`.toLocaleLowerCase())}"><span class="task-row-title"><span class="row-num">0${i+1}</span><span><strong>${escapeHtml(t.title)}</strong><small>${escapeHtml(t.industry)} <b>·</b> ${escapeHtml(t.created)}</small></span></span><span class="row-readiness"><span class="readiness-value"><strong>${t.score}</strong>${rarityBadge(t.score)}</span><span class="row-track"><i style="width:${t.score}%;background:linear-gradient(90deg,var(--red),var(--gold))"></i></span></span><span class="row-arrow">↗</span></button>`).join('')}<div id="overview-empty" hidden><strong>Задач не найдено</strong><p>Попробуйте другое название или измените фильтр.</p><button class="btn" id="overview-reset">Сбросить фильтры</button></div></div></section>
 <section class="recent-section"><div class="section-heading"><div><h2>Команды на связи</h2><p>Сравните предложения и выберите подход к задаче.</p></div><button class="text-link" data-view="offers">Все отклики ${icon('arrow')}</button></div><div class="recent-grid">${state.offers.slice(0,2).map(o=>{const team=state.teams.find(t=>t.id===o.teamId);return `<button class="recent-offer" data-view="offers"><span class="recent-top"><span class="team-avatar">${team.initials}</span><span><strong>${escapeHtml(team.name)}</strong><small>${escapeHtml(o.deadline)}</small></span><span class="offer-dot"></span></span><p>${escapeHtml(o.idea)}</p><span class="recent-bottom">${o.status==='accepted'?'Команда выбрана':'Рассмотреть предложение'} <span>↗</span></span></button>`}).join('')}</div></section></div>
 <aside class="focus-column"><section class="focus-card"><div class="eyebrow">Следующий шаг</div><div class="focus-symbol">${icon('offers')}</div><h2>${state.role==='team'?'Найдите задачу<br>для своей команды.':pending.length?'Идеи уже ждут<br>вашего решения.':'Начните с одной<br>понятной задачи.'}</h2><p>${pending.length?`${pending.length} предложения от команд. Ознакомьтесь с планом, обсудите детали и выберите, с кем двигаться дальше.`:'Опишите проблему. Мы поможем уточнить детали и подготовить задачу для команд.'}</p><button class="btn focus-button" data-view="${pending.length?'offers':state.role==='team'?'catalog':'create'}">${pending.length?'Сравнить предложения':state.role==='team'?'Открыть каталог':'Создать задачу'} ${icon('arrow')}</button><div class="focus-foot">Выбор команды всегда за вами.</div></section><section class="guide-card"><div class="eyebrow">Как устроена готовность</div><h3>Детали дают ясность.</h3><p>Данные, результат и критерии успеха помогают командам точнее оценить задачу.</p><div class="guide-scale"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><div class="guide-labels"><span>Идея</span><span>Готовая задача</span></div><button class="text-link" data-view="analytics">Посмотреть аналитику ↗</button></section></aside></div>`;
}
function recommendation(key) { return ({ context:'Опишите текущий процесс и конкретную боль в одном абзаце.', data:'Добавьте источник данных, пример записи или доступный набор материалов.', expected:'Сформулируйте артефакт, который команда должна передать бизнесу.', success:'Укажите измеримый порог: время, долю, количество или конверсию.', constraints:'Зафиксируйте срок, доступы и технологии, которые нельзя использовать.', users:'Назовите основную группу пользователей и её рабочий контекст.', business:'Укажите контакт, частоту консультаций и способ быстрой обратной связи.' })[key]; }
function renderCreate() {
  const d = state.draft; const score = scoreFor(d); const rows = breakdownFor(d); const isQuestion = state.draftStep === 2;
  return `<div class="page-heading"><div><h1>Конструктор задачи</h1><p>Опишите проблему, уточните детали и проверьте карточку перед публикацией.</p></div><div class="heading-actions"><button class="btn" data-action="reset-draft">Сбросить</button></div></div>
  ${analysisModeBanner()}<div class="stepper">${['Черновик','Уточнение','Карточка','Публикация'].map((x,i)=>`<div class="step ${state.draftStep === i+1 ? 'active' : state.draftStep > i+1 ? 'done':''}"><span class="num">${state.draftStep > i+1 ? '✓' : i+1}</span>${x}</div>`).join('')}</div>
  ${state.draftStep === 1 ? renderDraftStep(d) : state.draftStep === 2 ? renderQuestionsStep(d) : renderCardStep(d, score, rows)}
  `;
}
function renderDraftStep(d) { return `<div class="form-layout"><div class="card form-card"><div class="ai-banner"><div class="ai-orb">→</div><div><strong>Начните с проблемы</strong><p>Опишите проблему своими словами. Мы выделим контекст и предложим вопросы именно по недостающим сведениям.</p></div></div><div class="field"><label for="raw">Что нужно изменить?</label><textarea class="textarea" id="raw" placeholder="Например: менеджеры вручную переносят заявки из почты в таблицу, из-за этого теряются обращения...">${escapeHtml(d.raw)}</textarea></div><div class="form-grid" style="margin-top:15px"><div class="field"><label for="industry">Отрасль</label><select class="select" id="industry">${['Сервисы','Образование','Госуслуги','Ритейл','Здравоохранение','Другое'].map(x=>`<option ${d.industry===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="contact">Контакт бизнеса <span>(необязательно)</span></label><input class="input" id="contact" value="${escapeHtml(d.contact)}" placeholder="Имя и роль" /></div></div><div style="display:flex;justify-content:flex-end;margin-top:18px"><button class="btn" id="load-example">Пример для демо</button><button class="btn primary" data-action="analyze">Уточнить задачу →</button></div></div><div class="card score-panel"><div class="section-title"><h3>Как это работает</h3><span>3 шага</span></div><div class="journey" style="display:grid;gap:15px;padding:2px 0"><div class="journey-step" style="display:flex;gap:10px;text-align:left;align-items:center"><div class="journey-dot" style="margin:0">1</div><div><strong>AI находит пробелы</strong><span>Проверка источников</span></div></div><div class="journey-step" style="display:flex;gap:10px;text-align:left;align-items:center"><div class="journey-dot" style="margin:0;background:var(--purple-soft);color:var(--purple)">2</div><div><strong>Бизнес подтверждает</strong><span>Карточка редактируется</span></div></div><div class="journey-step" style="display:flex;gap:10px;text-align:left;align-items:center"><div class="journey-dot" style="margin:0;background:var(--green-soft);color:var(--green)">3</div><div><strong>Команды выбираются</strong><span>Никакого автоподбора</span></div></div></div></div></div>`; }
function renderQuestionsStep(d) { return `<div class="form-layout"><div class="card form-card"><div class="ai-banner"><div class="ai-orb">→</div><div><strong>Нашли ${d.questions.length} точки роста</strong><p>Ответьте на вопросы — ответы попадут в редактируемую карточку. Если вопрос не подходит, его можно пропустить.</p></div></div><div class="questions">${d.questions.map((q,i)=>`<div class="question"><div class="q-top"><strong>${i+1}. ${escapeHtml(q.question)}</strong><small>поле: ${escapeHtml(fieldLabels[q.field] || q.field)}</small></div><textarea class="textarea question-answer" data-field="${q.field}" placeholder="Ваш ответ..." style="min-height:76px;margin-top:9px">${escapeHtml(d[q.field] || '')}</textarea></div>`).join('')}</div><div style="display:flex;justify-content:space-between;gap:10px;margin-top:18px"><button class="btn" data-action="back-step">← Назад</button><button class="btn primary" data-action="build-card">Собрать карточку →</button></div></div><div class="card score-panel"><div class="section-title"><h3>Принцип доверия</h3></div><div class="insight" style="margin-bottom:12px"><div class="insight-icon">⌁</div><div><strong>Только ваши факты</strong><p>Поля заполняются фрагментами исходного описания и вашими ответами. Проверьте их смысл перед публикацией.</p></div></div><div class="section-title" style="margin-top:20px"><h3>Сейчас известно</h3></div><div class="task-meta">${d.industry ? `<span>◈ ${escapeHtml(d.industry)}</span>` : ''}${d.contact ? `<span>♙ ${escapeHtml(d.contact)}</span>` : ''}</div></div></div>`; }
function renderCardStep(d, score, rows) { return `<div class="form-layout"><div class="card form-card"><div class="ai-banner"><div class="ai-orb">✓</div><div><strong>Карточка готова к редактуре</strong><p>Проверьте формулировки и добавьте точные детали. Рейтинг изменяется в реальном времени.</p></div></div><div class="form-grid"><div class="field full"><label>Название задачи</label><input class="input draft-field" data-field="title" value="${escapeHtml(d.title)}" placeholder="Короткое название результата" /></div>${Object.keys(fieldLabels).map(key=>`<div class="field ${key==='context'||key==='data'||key==='expected'||key==='success'?'full':''}"><label>${fieldLabels[key]} <span>до ${weights[key]} баллов</span></label><textarea class="textarea draft-field" data-field="${key}" style="min-height:78px">${escapeHtml(d[key])}</textarea></div>`).join('')}<div class="field"><label>Формат взаимодействия</label><select class="select draft-field" data-field="interaction">${['Онлайн-встречи','Чат и еженедельный созвон','Гибридно','Асинхронно'].map(x=>`<option ${d.interaction===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Контакт</label><input class="input draft-field" data-field="contact" value="${escapeHtml(d.contact)}" /></div></div><label class="publish-check"><input type="checkbox" id="confirm-card" ${d.confirmed?'checked':''} /><span>Я подтверждаю, что сведения в карточке предоставлены бизнесом и готовы к публикации.</span></label><div style="display:flex;justify-content:space-between;gap:10px"><button class="btn" data-action="back-step">← Вопросы</button><button class="btn primary" data-action="publish-draft" ${d.confirmed?'':'disabled'}>Подтвердить и опубликовать →</button></div></div><div class="card score-panel"><div class="section-title"><h3>Readiness DNA</h3><span>критерии конкретности</span></div><div class="score-big"><div class="score-number">${score}</div><div class="score-caption"><strong>${levelFor(score)}</strong><span>готовность задачи</span></div></div><div class="progress" style="height:10px;margin-bottom:18px"><i style="width:${score}%"></i></div><div class="breakdown">${rows.map(row=>`<div class="breakdown-row"><div><div class="label"><span>${row.label}</span><b>${row.points}/${row.weight}</b></div><div class="progress"><i style="width:${Math.round(row.points/row.weight*100)}%"></i></div><small class="score-reason">${escapeHtml(row.reason)}</small></div></div>`).join('')}</div>${nextActions(d).length ? `<div class="missing"><h4>Что повысит рейтинг</h4><ul>${nextActions(d).map(a=>`<li>${a.label}: ещё +${a.weight-a.points}</li>`).join('')}</ul></div>` : ''}</div></div>`; }
function taskCard(task, showMatch=false) { const match = null; return `<div class="card task-card"><div class="task-card-head"><div><h3>${escapeHtml(task.title)}</h3><p>${escapeHtml(task.context)}</p></div><div class="task-rarity"><strong>${task.score}<small>/100</small></strong>${rarityBadge(task.score)}</div></div><div class="task-meta"><span>◈ ${escapeHtml(task.industry)}</span><span>◷ ${escapeHtml(task.created)}</span>${task.tags.map(x=>`<span>#${escapeHtml(x)}</span>`).join('')}</div><div class="task-score"><div class="progress"><i style="width:${task.score}%"></i></div><strong>${task.score}%</strong></div>${match ? `<div class="insight" style="margin-top:14px;padding:10px;background:var(--purple-soft);border-color:#ded8fa"><div class="insight-icon" style="background:white">→</div><div><strong style="color:#5d4cab">${match}% совпадение с Data Nomads</strong><p style="color:#746b9d">${matchReason(task)}</p></div></div>` : ''}<div style="display:flex;justify-content:flex-end;margin-top:14px"><button class="btn soft small" data-task="${task.id}">Подробнее <span aria-hidden="true">↗</span></button></div></div>`; }
function renderCatalog() { const tasks = state.tasks.filter(t=>t.status==='published'); return `<div class="page-heading"><div><h1>Открытый каталог задач</h1><p>Все опубликованные задачи доступны командам — независимо от рейтинга.</p></div><div class="heading-actions"><span class="badge green">● ${tasks.length} опубликовано</span></div></div><div class="catalog-toolbar"><input class="input" id="catalog-search" placeholder="Поиск по задачам..." /><select class="select" id="catalog-industry"><option value="">Все отрасли</option>${[...new Set(tasks.map(t=>t.industry))].map(x=>`<option>${escapeHtml(x)}</option>`).join('')}</select><select class="select" id="catalog-level"><option value="">Все уровни</option>${['Приоритетная','Готовая','Рабочая','Черновик'].map(x=>`<option>${escapeHtml(x)}</option>`).join('')}</select><select class="select" id="catalog-sort"><option value="score">Сначала готовые</option><option value="new">Сначала новые</option></select></div><div id="catalog-list" class="grid grid-2">${tasks.sort((a,b)=>b.score-a.score).map(t=>taskCard(t,state.role==='team')).join('')}</div>`; }
function matchFor(task) { const text = `${task.title} ${task.context} ${task.tags.join(' ')}`.toLowerCase(); const keywords = ['данные','автоматизация','образование','город','ai','классификация','рекомендации']; return Math.min(98, 58 + keywords.filter(k=>text.includes(k)).length*7); }
function matchReason(task) { return task.tags.includes('AI') ? 'Сильное совпадение по NLP и ML.' : task.tags.includes('автоматизация') ? 'Сильное совпадение по Python и процессам.' : 'Совпадают интересы и формат прототипирования.'; }
function renderAnalytics() { const tasks = state.tasks.filter(t=>t.status==='published'); const avg = tasks.length?Math.round(tasks.reduce((a,t)=>a+t.score,0)/tasks.length):0; return `<div class="page-heading"><div><h1>Аналитика пространства</h1><p>Показываем не только результат, но и путь от идеи до решения.</p></div><div class="heading-actions"><button class="btn soft" data-action="export">Экспорт данных</button></div></div><div class="card section-card" style="margin-bottom:18px"><div class="kpi-strip"><div class="kpi"><strong>${avg}</strong><span>средняя готовность</span></div><div class="kpi"><strong>${tasks.filter(t=>t.score>=70).length}</strong><span>готовых задач</span></div><div class="kpi"><strong>${state.offers.length}</strong><span>всего откликов</span></div><div class="kpi"><strong>${state.offers.filter(o=>o.status==='accepted').length}</strong><span>ручных решений</span></div></div></div><div class="grid grid-2"><div class="card section-card"><div class="section-title"><h3>Путь задачи</h3><span>сквозной сценарий</span></div><div class="journey">${[['01','Черновик','сырой текст'],['02','Уточнение','AI-вопросы'],['03','Карточка','проверка бизнеса'],['04','Каталог','открытые задачи'],['05','Решение','ручной выбор']].map(x=>`<div class="journey-step"><div class="journey-dot">${x[0]}</div><strong>${x[1]}</strong><span>${x[2]}</span></div>`).join('')}</div></div><div class="card section-card"><div class="section-title"><h3>Распределение задач</h3><span>готовность</span></div>${['Приоритетная','Готовая','Рабочая','Черновик'].map(l=>{const n=tasks.filter(t=>t.level===l).length; return `<div class="readiness-row" style="grid-template-columns:110px 1fr 28px;margin-bottom:12px"><label>${l}</label><div class="progress"><i style="width:${(tasks.length?n/tasks.length*100:0)}%;background:${l==='Приоритетная'?'var(--purple)':l==='Готовая'?'var(--green)':l==='Рабочая'?'var(--blue)':'var(--orange)'}"></i></div><strong>${n}</strong></div>`}).join('')}</div></div><div class="card section-card" style="margin-top:18px"><div class="section-title"><h3>Открытый каталог</h3><span>отклики доступны для любой задачи</span></div><div class="grid grid-3">${tasks.slice(0,3).map(t=>`<div class="task-card" style="box-shadow:none"><div class="task-card-head"><h3>${escapeHtml(t.title)}</h3><span class="badge ${levelClass(t.level)}">${t.score}</span></div><p style="margin-top:8px">${escapeHtml(t.level)} · ${escapeHtml(t.industry)}</p></div>`).join('')}</div></div>`; }
function filterOverview() {
 const table=document.querySelector('.task-table'); if(!table)return;
 const query=(document.getElementById('overview-search')?.value||'').trim().toLocaleLowerCase();
 const mode=document.querySelector('[data-readiness].active')?.dataset.readiness||'all';
 const sort=document.getElementById('overview-sort')?.value||'default';
 const rows=Array.from(table.querySelectorAll('.task-row'));
 rows.sort((a,b)=>sort==='score'?Number(b.dataset.score)-Number(a.dataset.score):sort==='gaps'?Number(a.dataset.score)-Number(b.dataset.score):Number(a.dataset.order)-Number(b.dataset.order));
 let visible=0;const empty=document.getElementById('overview-empty');
 rows.forEach(row=>{row.hidden=!(row.dataset.search.includes(query)&&(mode==='all'||(mode==='ready'?Number(row.dataset.score)>=70:Number(row.dataset.score)<70)));if(!row.hidden)visible++;table.insertBefore(row,empty);});
 document.getElementById('overview-count').textContent=`${visible} из ${rows.length}`;
 empty.hidden=visible>0;
}
function bindEvents() {
 document.getElementById('logout')?.addEventListener('click',logout);
 document.getElementById('load-example')?.addEventListener('click',()=>{state.draft.raw=DEMO_CASE.raw;document.getElementById('raw').value=state.draft.raw;saveState();});
 document.getElementById('use-local')?.addEventListener('click',()=>{state.forceLocal=true;render();});
 document.getElementById('use-llm')?.addEventListener('click',()=>{state.forceLocal=false;render();});
 document.querySelectorAll('.question-answer').forEach(el=>el.addEventListener('input',()=>{state.draft[el.dataset.field]=el.value;saveState();}));
 document.getElementById('overview-search')?.addEventListener('input',filterOverview);
 document.getElementById('overview-sort')?.addEventListener('change',filterOverview);
 document.querySelectorAll('[data-readiness]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-readiness]').forEach(item=>{item.classList.toggle('active',item===btn);item.setAttribute('aria-pressed',String(item===btn));});filterOverview();}));
 document.getElementById('overview-reset')?.addEventListener('click',()=>{document.getElementById('overview-search').value='';document.getElementById('overview-sort').value='default';document.querySelector('[data-readiness="all"]').click();});
  document.querySelectorAll('[data-view]').forEach(btn=>btn.addEventListener('click',()=>{ state.view=btn.dataset.view; if(state.view==='create' && state.draftStep===4) state.draftStep=1; saveState(); render(); }));
  document.querySelectorAll('[data-role]').forEach(btn=>btn.addEventListener('click',()=>{ if(!DEMO)return;state.role=btn.dataset.role; state.view='dashboard';closeModal();saveState(); render(); }));
  document.querySelectorAll('[data-action="new-task"]').forEach(btn=>btn.addEventListener('click',()=>{if(state.editingId){state.draft=structuredClone(initialState.draft);state.editingId=null;}state.view='create';state.draftStep=1;saveState();render();}));
  document.querySelectorAll('[data-action="reset-draft"]').forEach(btn=>btn.addEventListener('click',()=>{ state.draft=structuredClone(initialState.draft);state.editingId=null;state.draftStep=1;saveState();render(); }));
  const raw = document.getElementById('raw'); if(raw) raw.addEventListener('input', e=>{state.draft.raw=e.target.value;state.draft.confirmed=false;saveState();});
  const industry = document.getElementById('industry'); if(industry) industry.addEventListener('change', e=>{state.draft.industry=e.target.value;saveState();});
  const contact = document.getElementById('contact'); if(contact) contact.addEventListener('input', e=>{state.draft.contact=e.target.value;saveState();});
  document.querySelectorAll('[data-action="analyze"]').forEach(btn=>btn.addEventListener('click', analyzeDraft));
  document.querySelectorAll('[data-action="back-step"]').forEach(btn=>btn.addEventListener('click',()=>{state.draftStep=Math.max(1,state.draftStep-1);saveState();render();}));
  document.querySelectorAll('[data-action="build-card"]').forEach(btn=>btn.addEventListener('click',buildCard));
  document.querySelectorAll('.draft-field').forEach(el=>el.addEventListener('input', e=>{state.draft[e.target.dataset.field]=e.target.value;state.draft.confirmed=false;const c=document.getElementById('confirm-card');if(c)c.checked=false;refreshCreateOnly();}));
  const confirm = document.getElementById('confirm-card'); if(confirm) confirm.addEventListener('change', e=>{state.draft.confirmed=e.target.checked; saveState(); render();});
  document.querySelectorAll('[data-action="publish-draft"]').forEach(btn=>btn.addEventListener('click',publishDraft));
  document.querySelectorAll('[data-task]').forEach(btn=>btn.addEventListener('click',()=>openTask(btn.dataset.task)));
  document.querySelectorAll('[data-offer]').forEach(btn=>btn.addEventListener('click',()=>decideOffer(btn.dataset.offer,btn.dataset.decision)));
  const search=document.getElementById('catalog-search'); const ind=document.getElementById('catalog-industry'); const lev=document.getElementById('catalog-level'); const sort=document.getElementById('catalog-sort');
  [search,ind,lev,sort].filter(Boolean).forEach(el=>el.addEventListener('input',()=>filterCatalog()));
  document.querySelectorAll('[data-action="export"]').forEach(btn=>btn.addEventListener('click',exportData));
}
function titleFromDraft(raw) { const clean=raw.replace(/^[\s.,!?;:—–-]+/,'').split(/[.!?\n]/)[0].trim(); return clean.length>64 ? clean.slice(0,61)+'…' : clean || 'Новая бизнес-задача'; }
function filterCatalog() { const q=(document.getElementById('catalog-search')?.value||'').toLowerCase(); const ind=document.getElementById('catalog-industry')?.value||''; const lev=document.getElementById('catalog-level')?.value||''; const sort=document.getElementById('catalog-sort')?.value||'score'; const tasks=state.tasks.filter(t=>t.status==='published').filter(t=>(!q||`${t.title} ${t.context} ${t.tags.join(' ')}`.toLowerCase().includes(q))&&(!ind||t.industry===ind)&&(!lev||t.level===lev)).sort((a,b)=>sort==='new' ? b.id.localeCompare(a.id) : b.score-a.score); const list=document.getElementById('catalog-list'); if(list)list.innerHTML=tasks.length?tasks.map(t=>taskCard(t,state.role==='team')).join(''):`<div class="card empty" style="grid-column:1/-1"><div class="empty-icon">⌕</div>Ничего не нашли. Попробуйте изменить фильтр.</div>`; document.querySelectorAll('[data-task]').forEach(btn=>btn.addEventListener('click',()=>openTask(btn.dataset.task))); }
function closeModal(){document.getElementById('modal-root').innerHTML='';}



function currentIdentity(){return DEMO?{id:state.role==='team'?'team1':'business',name:state.role==='team'?'Data Nomads':'Анса',role:state.role}:authUser||{id:'',name:'',role:'business'};}
function loadState(){
 const empty={...structuredClone(initialState),tasks:[],teams:[],offers:[],editingId:null};
 if(!DEMO)return empty;
 try{
  const saved=JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}');
  const loaded={...structuredClone(initialState),...saved};
  for(const key of ['tasks','teams','offers']){
   const rows=Array.isArray(saved[key])?saved[key]:[];const ids=new Set(rows.map(row=>row.id));
   loaded[key]=[...rows,...initialState[key].filter(seed=>!ids.has(seed.id)).map(seed=>structuredClone(seed))];
  }
  return loaded;
 }catch{return structuredClone(initialState)}
}
function saveState(){
 try{if(DEMO)localStorage.setItem(STORAGE_KEY,JSON.stringify(state));else if(authUser)localStorage.setItem('taskready-draft-'+authUser.id,JSON.stringify({draft:state.draft,draftStep:state.draftStep,editingId:state.editingId}));}catch{toast('Браузер не смог сохранить черновик. Не закрывайте вкладку.');}
}
function calculate(card){
 const breakdown=Object.entries(RUBRIC.fields).map(([key,s])=>{
  const text=String(card[key]||'').trim(); const words=text.toLowerCase().match(/[\p{L}\p{N}_]+/gu)||[];
  const valid=new Set(words).size>=3&&!/^(не знаю|не определен[ыоа]?|уточняется|пока неизвестно|нет|потом|tbd|n\/?a)[.!\s]*$/i.test(text);
  const checks=s.checks.map(c=>({...c,passed:valid&&new RegExp(c.pattern,'i').test(text)}));
  const points=Math.round(s.weight*checks.filter(c=>c.passed).length/checks.length);
  return {key,label:s.label,weight:s.weight,points,checks,reason:checks.filter(c=>!c.passed).map(c=>c.label).join('; ')||'Оба признака конкретности найдены'};
 });const score=breakdown.reduce((a,b)=>a+b.points,0);return {score,level:levelFor(score),breakdown};
}
function scoreFor(card){return calculate(card).score;}
function breakdownFor(card){return calculate(card).breakdown;}
function refreshCreateOnly(){
 const sc=calculate(state.draft);document.querySelector('.score-number').textContent=sc.score;
 document.querySelector('.score-caption strong').textContent=sc.level;
 document.querySelectorAll('.breakdown-row').forEach((row,i)=>{const v=sc.breakdown[i];row.querySelector('b').textContent=`${v.points}/${v.weight}`;row.querySelector('i').style.width=`${v.points/v.weight*100}%`;row.querySelector('.score-reason').textContent=v.reason;});
 const bar=document.querySelector('.score-panel>.progress>i');if(bar)bar.style.width=sc.score+'%';
 const pub=document.querySelector('[data-action="publish-draft"]');if(pub)pub.disabled=!state.draft.confirmed;
 const panel=document.querySelector('.score-panel');let missing=panel.querySelector('.missing');const gaps=sc.breakdown.filter(r=>r.points<r.weight).sort((a,b)=>(b.weight-b.points)-(a.weight-a.points)).slice(0,3);if(gaps.length){if(!missing){missing=document.createElement('div');missing.className='missing';panel.appendChild(missing);}missing.hidden=false;missing.innerHTML='<h4>Что повысит рейтинг</h4><ul>'+gaps.map(r=>`<li>${escapeHtml(r.reason)}</li>`).join('')+'</ul>';}else if(missing)missing.hidden=true;
 saveState();
}
async function api(path,method='GET',data){
 const response=await fetch('/api'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json',...(csrfToken?{'X-CSRF-Token':csrfToken}:{})},...(data===undefined?{}:{body:JSON.stringify(data)}),signal:AbortSignal.timeout(45000)});
 let result;try{result=await response.json()}catch{throw Error('Сервер вернул неожиданный ответ. Попробуйте снова.');}
 if(!response.ok){if(response.status===401){authUser=null;render();}throw Error(typeof result.detail==='string'?result.detail:'Проверьте заполнение полей.');}return result;
}
async function syncState(){const remote=await api('/state');state.tasks=remote.tasks;state.offers=remote.offers;state.teams=remote.teams;state.role=remote.user.role;authUser=remote.user;aiConfigured=remote.aiConfigured;}
async function busy(selector,action){if(working)return;working=true;const btn=document.querySelector(selector);const text=btn?.textContent;if(btn){btn.disabled=true;btn.textContent='Подождите…';}try{await action();}catch(e){toast(e.name==='TimeoutError'?'Сервер не ответил вовремя. Попробуйте ещё раз.':e.message||'Ошибка соединения. Повторите запрос.');}finally{working=false;if(btn?.isConnected){btn.disabled=false;btn.textContent=text;}}}
async function bootstrapServer(){
 if(DEMO){state.tasks.forEach(t=>Object.assign(t,calculate(t)));render();return;}
 document.getElementById('app').innerHTML='<div class="app-loading">Открываем рабочее пространство…</div>';
 try{const health=await api('/health');aiConfigured=health.aiConfigured;const me=await api('/auth/me');authUser=me.user;csrfToken=me.csrfToken;await syncState();try{const draft=JSON.parse(localStorage.getItem('taskready-draft-'+authUser.id)||'null');if(draft)Object.assign(state,draft);}catch{}render();}catch(e){if(!authUser)renderAuth();else{document.getElementById('app').innerHTML='<div class="app-loading"><h2>Не удалось загрузить данные</h2><p>Проверьте соединение и обновите страницу.</p></div>';}}
}
function render(){if(!DEMO&&!authUser){renderAuth();return;}if(state.role==='team'&&state.view==='create')state.view='catalog';renderShell();if(state.view==='dashboard')filterOverview();}
function renderAuth(registerMode=false){
 document.getElementById('app').innerHTML=`<main class="auth-layout"><section class="auth-story"><div class="brand"><div class="brand-mark">${icon('check')}</div><div><strong>taskready.</strong><small>От идеи к результату</small></div></div><span class="eyebrow">ЗАДАЧА НАЧИНАЕТСЯ С ЯСНОСТИ</span><h1>Хорошие идеи.<br><em>Общая работа.</em></h1><p>Подготовьте понятный бриф, найдите команду и подтвердите результат.</p><ol><li><span>01</span> Уточните задачу и критерии успеха</li><li><span>02</span> Сравните предложения команд</li><li><span>03</span> Зафиксируйте прогресс</li></ol><a href="/demo.html">Сначала посмотреть автономное демо ↗</a></section><section class="auth-form-wrap"><form id="auth-form" class="auth-form"><div class="eyebrow">ВАШЕ ПРОСТРАНСТВО</div><h2>${registerMode?'Создать аккаунт':'С возвращением'}</h2><p>${registerMode?'Выберите роль. У каждой свой набор действий.':'Войдите, чтобы продолжить работу.'}</p>${registerMode?`<label>Ваше имя или название команды<input class="input" name="name" required minlength="2" maxlength="80" autocomplete="name"></label><label>Роль<select class="select" name="role"><option value="business">Бизнес — публикую задачи</option><option value="team">Команда — предлагаю решения</option></select></label>`:''}<label>Email<input class="input" name="email" type="email" required maxlength="160" autocomplete="email"></label><label>Пароль<input class="input" name="password" type="password" required minlength="10" maxlength="128" autocomplete="${registerMode?'new-password':'current-password'}"></label><small>Не менее 10 символов.</small><p id="auth-error" class="form-error" role="alert"></p><button class="btn primary" type="submit">${registerMode?'Зарегистрироваться':'Войти'} ${icon('arrow')}</button><button class="text-link auth-toggle" type="button">${registerMode?'Уже есть аккаунт? Войти':'Нет аккаунта? Зарегистрироваться'}</button></form></section></main>`;
 document.querySelector('.auth-toggle').onclick=()=>renderAuth(!registerMode);
 document.getElementById('auth-form').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('[type="submit"]');btn.disabled=true;const data=Object.fromEntries(new FormData(e.target));try{const r=await api(registerMode?'/auth/register':'/auth/login','POST',data);authUser=r.user;csrfToken=r.csrfToken;state=loadState();await syncState();render();}catch(err){const box=document.getElementById('auth-error');if(box)box.textContent=err.message;}finally{btn.disabled=false;}};
}
async function logout(){await busy('#logout',async()=>{await api('/auth/logout','POST',{});localStorage.removeItem('taskready-draft-'+authUser.id);authUser=null;csrfToken='';state=loadState();closeModal();render();});}
function analysisModeBanner(){
 const local=DEMO||state.forceLocal||!aiConfigured;
 return `<div class="mode-banner ${local?'local':'llm'}"><span><b>${local?'Локальная проверка':'AI-анализ подключён'}</b> · ${local?'прозрачные правила, без внешней модели':'факты из ваших ответов, с проверкой источников'}</span>${!DEMO&&aiConfigured?`<button class="text-link" id="${local?'use-llm':'use-local'}">${local?'Использовать AI':'Локальный режим'}</button>`:''}</div>`;
}
const DEMO_CASE={raw:'Менеджеры вручную переносят заявки из почты в таблицу. Часть обращений теряется, а команда тратит 4 часа в неделю на копирование.',answers:{context:'Менеджеры отдела продаж вручную переносят заявки из почты в таблицу и теряют обращения.',data:'Доступна выгрузка CSV: 150 заявок за месяц и 20 обезличенных примеров.',expected:'Прототип импорта и маршрутизации заявок в единый реестр.',success:'Не менее 80% заявок попадают в реестр без ручного копирования, экономия 4 часов в неделю.',constraints:'MVP за 2 недели, без доступа к продакшену.',users:'Менеджеры отдела продаж, ежедневно обрабатывающие входящие заявки.',business:'Ответственный — руководитель отдела; еженедельный созвон по пятницам.'}};
const LOCAL_QUESTIONS={context:'Какой процесс не работает и какие потери он создаёт?',data:'Какие данные доступны: источник, формат, объём и права доступа?',expected:'Какой результат команда должна передать и что он должен уметь?',success:'Какой измеримый порог покажет, что задача решена?',constraints:'Каков срок и какие ограничения нужно учитывать?',users:'Кто использует результат и в какой рабочей ситуации?',business:'Кто отвечает за задачу и как часто доступен для обратной связи?'};
function localAnalysis(raw,answers={}){const card={...answers,context:answers.context||raw};const gaps=breakdownFor(card).sort((a,b)=>(b.weight-b.points)-(a.weight-a.points));return {card,questions:gaps.slice(0,5).map(r=>({field:r.key,question:LOCAL_QUESTIONS[r.key]})),mode:'local',evidence:[]};}
async function analyzeDraft(){
 if(state.role!=='business')return;
 if(state.draft.raw.trim().length<15){toast('Опишите проблему подробнее: минимум 15 символов.');return;}
 await busy('[data-action="analyze"]',async()=>{
  const raw=state.draft.raw.trim(), local=DEMO||state.forceLocal||!aiConfigured;
  const result=DEMO?localAnalysis(raw):await api('/tasks/analyze','POST',{raw,answers:{},local});
  const meta={industry:state.draft.industry,contact:state.draft.contact};
  state.draft={...structuredClone(initialState.draft),...meta,...result.card,raw,title:titleFromDraft(raw),questions:result.questions,mode:result.mode,evidence:result.evidence,clientId:crypto.randomUUID(),confirmed:false};
  state.draftStep=2;saveState();render();toast(result.mode==='llm'?'AI подготовил вопросы.':'Вопросы подготовлены локальными правилами.');
 });
}
async function buildCard(){
 document.querySelectorAll('.question-answer').forEach(el=>state.draft[el.dataset.field]=el.value);
 await busy('[data-action="build-card"]',async()=>{const d=state.draft;const answers=Object.fromEntries(Object.keys(fieldLabels).map(k=>[k,d[k]||'']));
 if(!DEMO&&d.mode==='llm'&&!state.forceLocal){const result=await api('/tasks/analyze','POST',{raw:d.raw,answers,local:false});Object.assign(d,result.card,{evidence:result.evidence});}
 d.title=d.title||titleFromDraft(d.raw);d.confirmed=false;state.draftStep=3;saveState();render();});
}
function cardPayload(d){return Object.fromEntries(['title','industry',...Object.keys(fieldLabels),'contact','interaction','confirmed','clientId'].map(k=>[k,k==='confirmed'?!!d[k]:d[k]||'']));}
async function publishDraft(){
 if(!state.draft.confirmed||state.role!=='business')return;
 if(state.draft.title.trim().length<3||state.draft.context.trim().length<15){toast('Добавьте название и описание задачи.');return;}
 await busy('[data-action="publish-draft"]',async()=>{const d=state.draft;d.clientId=d.clientId||crypto.randomUUID();saveState();
 if(DEMO){const task={...cardPayload(d),...calculate(d),id:state.editingId||'t'+crypto.randomUUID(),owner:'business',version:(d.version||0)+1,status:'published',created:'Сегодня',createdAt:Date.now()/1000,tags:[d.industry]};const ix=state.tasks.findIndex(t=>t.id===task.id);if(ix>=0)state.tasks[ix]=task;else state.tasks.unshift(task);}
 else{await api(state.editingId?'/tasks/'+state.editingId:'/tasks',state.editingId?'PUT':'POST',{...cardPayload(d),...(state.editingId?{version:d.version}:{})});await syncState();}
 state.draft=structuredClone(initialState.draft);state.editingId=null;state.draftStep=1;state.view='catalog';saveState();render();toast('Задача опубликована.');});
}
function safeLink(v){try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)?escapeHtml(u.href):''}catch{return ''}}
function openTask(id){
 const t=state.tasks.find(t=>t.id===id);if(!t)return;
 const mine=state.role==='business'&&t.owner===currentIdentity().id;const existing=state.offers.find(o=>o.taskId===id&&o.teamId===currentIdentity().id);
 document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="task-modal-title"><div class="modal-head"><div><span class="badge green">${t.score}/100 · ${escapeHtml(t.level)}</span><h2 id="task-modal-title">${escapeHtml(t.title)}</h2><p>${escapeHtml(t.industry)}</p></div><button class="close" data-close aria-label="Закрыть">×</button></div><div class="detail-grid">${Object.keys(fieldLabels).map(k=>`<div class="detail-item"><span>${fieldLabels[k]}</span><b>${escapeHtml(t[k]||'Не заполнено')}</b></div>`).join('')}</div><details class="score-details"><summary>Почему ${t.score} баллов? · Readiness DNA</summary>${breakdownFor(t).map(r=>`<p><b>${r.label} — ${r.points}/${r.weight}</b><br>${escapeHtml(r.reason)}</p>`).join('')}<small>Проверка конкретности, не гарантия достоверности или реализуемости.</small></details>${mine?'<button class="btn" id="edit-task">Редактировать карточку</button>':''}${state.role==='team'?(existing?`<div class="mode-banner">Ваш отклик уже отправлен: ${statusLabel(existing.status)}</div>`:`<form id="offer-form"><h3>Предложить решение</h3><label>Идея<textarea class="textarea" id="offer-idea" required minlength="10" maxlength="3000"></textarea></label><label>План<textarea class="textarea" id="offer-plan" required minlength="10" maxlength="3000"></textarea></label><label>Срок<input class="input" id="offer-deadline" required minlength="2" maxlength="100" placeholder="Например, 10 дней"></label><label>Ссылка на прототип<input class="input" id="offer-link" type="url" required maxlength="500" placeholder="https://example.com/prototype"></label><small class="score-reason">Добавьте ссылку на прототип в Figma, GitHub или веб-демо.</small><button class="btn primary" data-submit-offer="${id}">Отправить предложение</button></form>`):''}</section></div>`;
 bindModal();document.getElementById('offer-form')?.addEventListener('submit',e=>{e.preventDefault();submitOffer(id)});
 document.getElementById('edit-task')?.addEventListener('click',()=>{state.draft={...structuredClone(initialState.draft),...t,raw:t.context,questions:[],confirmed:false,clientId:crypto.randomUUID()};state.editingId=t.id;state.draftStep=3;state.view='create';closeModal();render();});
}
function bindModal(){document.querySelector('[data-close]')?.addEventListener('click',closeModal);document.querySelector('.modal-backdrop')?.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()});document.querySelector('.modal [data-close]')?.focus();}
async function submitOffer(taskId){await busy('[data-submit-offer]',async()=>{
 if(state.role!=='team')throw Error('Предложение отправляет аккаунт команды.');
 const payload={taskId,idea:document.getElementById('offer-idea').value.trim(),plan:document.getElementById('offer-plan').value.trim(),deadline:document.getElementById('offer-deadline').value.trim(),prototype:document.getElementById('offer-link').value.trim()};
 if(!safeLink(payload.prototype))throw Error('Добавьте корректную ссылку на прототип с http:// или https://.');
 if(DEMO){if(state.offers.some(o=>o.taskId===taskId&&o.teamId==='team1'))throw Error('Вы уже отправили отклик.');state.offers.push({...payload,id:'o'+crypto.randomUUID(),teamId:'team1',status:'pending',created:'Сегодня',progressConfirmed:false});saveState();}else{await api('/offers','POST',payload);await syncState();}
 closeModal();state.view='offers';render();toast('Предложение отправлено.');});}
function statusLabel(s){return ({pending:'На рассмотрении',accepted:'Команда выбрана',rejected:'Отклонено'})[s]||s;}
function visibleOffers(){return state.role==='team'?state.offers.filter(o=>o.teamId===currentIdentity().id):state.offers.filter(o=>state.tasks.find(t=>t.id===o.taskId)?.owner===currentIdentity().id);}
function renderOffers(){const offers=visibleOffers(),team=state.teams.find(t=>t.id===currentIdentity().id);return `<div class="page-heading"><div><h1>${state.role==='team'?'Мои предложения':'Комната решений'}</h1><p>Планы, решения и подтверждённые результаты в одном месте.</p></div><span class="badge green">${state.role==='team'?`${team?.points||0} баллов`:`${offers.filter(o=>o.status==='pending').length} ожидают решения`}</span></div><div class="grid grid-2">${offers.length?offers.map(offerCard).join(''):'<div class="card empty"><h3>Здесь появятся отклики</h3><p>Команды отправляют предложения из каталога задач.</p><button class="btn" data-view="catalog">Открыть каталог</button></div>'}</div>`;}
function offerCard(o){
 const task=state.tasks.find(t=>t.id===o.taskId),team=state.teams.find(t=>t.id===o.teamId);const owner=state.role==='business'&&task?.owner===currentIdentity().id;const link=safeLink(o.prototype);
 return `<article class="card offer-card"><div class="offer-top"><div class="team-name"><div class="team-avatar">${escapeHtml(team?.initials||'К')}</div><div><h3>${escapeHtml(team?.name||'Команда')}</h3><p>${escapeHtml(task?.title||'Задача')}</p></div></div><span class="badge ${o.status==='accepted'?'green':o.status==='rejected'?'gray':'orange'}">${statusLabel(o.status)}</span></div><div class="offer-body"><strong>Идея</strong><p>${escapeHtml(o.idea)}</p><strong>План</strong><p>${escapeHtml(o.plan)}</p></div><div class="task-meta"><span>Срок: ${escapeHtml(o.deadline)}</span>${link?`<a href="${link}" target="_blank" rel="noopener noreferrer">Прототип ↗</a>`:''}</div>${o.progressConfirmed?`<div class="progress-confirmed">✓ Прогресс подтверждён · +10 баллов<p>${escapeHtml(o.progressEvidence||'Результат проверен бизнесом.')}</p></div>`:''}${owner&&o.status==='pending'?`<div class="offer-actions"><button class="btn danger" data-offer="${o.id}" data-decision="reject">Отклонить</button><button class="btn primary" data-offer="${o.id}" data-decision="accept">Выбрать команду</button></div>`:owner&&o.status==='accepted'&&!o.progressConfirmed?`<div class="offer-actions"><button class="btn" data-offer="${o.id}" data-decision="progress">Подтвердить прогресс</button></div>`:''}</article>`;
}
async function decideOffer(id,action){
 const offer=state.offers.find(o=>o.id===id);if(!offer)return;const task=state.tasks.find(t=>t.id===offer.taskId);if(state.role!=='business'||task?.owner!==currentIdentity().id){toast('Решение доступно только владельцу задачи.');return;}
 if(action==='progress'){if(offer.progressConfirmed)return;document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="progress-title"><div class="modal-head"><h2 id="progress-title">Подтвердить результат</h2><button class="close" data-close aria-label="Закрыть">×</button></div><p>Зафиксируйте, что вы проверили. За этот этап команда получит 10 баллов один раз.</p><form id="progress-form"><label>Что сделано<textarea id="progress-evidence" class="textarea" required minlength="10" maxlength="2000" placeholder="Например: проверили импорт на 20 тестовых заявках"></textarea></label><button class="btn primary" id="confirm-progress">Подтвердить</button></form></div></div>`;bindModal();document.getElementById('progress-form').onsubmit=e=>{e.preventDefault();confirmProgress(id)};return;}
 await busy(`[data-offer="${id}"][data-decision="${action}"]`,async()=>{const status=action==='accept'?'accepted':'rejected';if(DEMO){if(offer.status===status)return;if(offer.status!=='pending')throw Error('Решение уже принято.');offer.status=status;if(status==='accepted')state.teams.find(t=>t.id===offer.teamId).points+=5;saveState();}else{await api('/offers/'+id+'/decision','POST',{decision:status});await syncState();}render();toast(status==='accepted'?'Команда выбрана. Начислено 5 баллов за старт.':'Отклик отклонён.');});
}
async function confirmProgress(id){await busy('#confirm-progress',async()=>{const evidence=document.getElementById('progress-evidence').value.trim();if(evidence.length<10)throw Error('Опишите проверенный результат.');if(DEMO){const o=state.offers.find(o=>o.id===id);if(!o.progressConfirmed){o.progressConfirmed=true;o.progressEvidence=evidence;state.teams.find(t=>t.id===o.teamId).points+=10;saveState();}}else{await api('/offers/'+id+'/progress','POST',{evidence});await syncState();}closeModal();render();toast('Прогресс подтверждён.');});}
async function exportData(){try{const data=DEMO?{tasks:state.tasks,teams:state.teams,offers:visibleOffers()}:await api('/export');const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='taskready-export.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){toast(e.message)}}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
bootstrapServer();
